// swift-tools-version: 5.10
// The Swift package shared by the macOS and iOS apps (architecture
// section 13): the Rust core as an XCFramework (built by
// ../scripts/core.sh, not committed), the UniFFI bindings over it
// (generated by the same script), and LumiaKit, the hand-written layer
// the apps share: the client, the view models, the design tokens and the
// small components. Layouts belong to the apps.
import PackageDescription

let package = Package(
    name: "LumiaKit",
    platforms: [.macOS(.v14), .iOS(.v17)],
    products: [
        .library(name: "LumiaKit", targets: ["LumiaKit"]),
    ],
    targets: [
        .binaryTarget(name: "LumiaCore", path: "LumiaCore.xcframework"),
        .target(
            name: "LumiaFFI",
            dependencies: ["LumiaCore"],
            swiftSettings: [.unsafeFlags(["-suppress-warnings"])]
        ),
        .target(
            name: "LumiaKit",
            dependencies: ["LumiaFFI"],
        ),
        .testTarget(name: "LumiaKitTests", dependencies: ["LumiaKit"]),
    ]
)
